import os
import sys

import matplotlib.pyplot as plt
import pandas as pd
import seaborn as sns
from matplotlib import ticker


# ============================================================
# Visualize RankNet score distributions by Mayo score
#
# 1. Read the mean prediction scores generated by
#      4_calculate_uncertainty.py
#
# 2. Group prediction scores by Mayo score (M0-M3).
#
# 3. Plot the score distributions using boxplots and
#    overlaid individual data points.
#
# Output:
# Results/
#   <result_date>/
#     fold_<fold>/
#       <datatype>_box_plot.pdf
# ============================================================


def pltsettings(fontsize=10, figsize=(4, 3)):
    """
    Keep the original plotting style while avoiding environment-specific fonts.
    """
    plt.rcParams["font.size"] = fontsize
    plt.rcParams["figure.figsize"] = figsize
    plt.rcParams["figure.dpi"] = 300
    plt.rcParams["xtick.direction"] = "in"
    plt.rcParams["ytick.direction"] = "in"
    plt.rcParams["axes.linewidth"] = 1.0
    plt.rcParams["legend.fancybox"] = False
    plt.rcParams["legend.framealpha"] = 1
    plt.rcParams["legend.edgecolor"] = "black"
    plt.rcParams["legend.handlelength"] = 1
    plt.rcParams["legend.labelspacing"] = 5.0
    plt.rcParams["legend.handletextpad"] = 3.0
    plt.rcParams["legend.markerscale"] = 2
    plt.rcParams["legend.borderaxespad"] = 0.0


def read_pred(result_path, datatype):
    datafile = os.path.join(
        result_path,
        f"{datatype}_mean_score_and_uncertainty.csv",
    )
    data = pd.read_csv(datafile)

    required = {"label", "mean_score"}
    missing = required - set(data.columns)
    if missing:
        raise ValueError(
            f"{datafile} is missing required columns: {sorted(missing)}"
        )

    labels = data["label"]
    scores = data["mean_score"]
    return labels, scores


def make_plot_dataframe(labels, scores, class_names):
    """
    Convert per-class scores into the same long-form layout used by the
    original seaborn boxplot/stripplot code.
    """
    frames = []

    for class_value, class_name in enumerate(class_names):
        class_scores = scores[labels == class_value].reset_index(drop=True)
        frames.append(
            pd.DataFrame(
                {
                    "variable": class_name,
                    "value": class_scores,
                }
            )
        )

    return pd.concat(frames, ignore_index=True)


def box_plot(result_path, datatype, class_names):
    labels, scores = read_pred(result_path, datatype)

    fig, ax = plt.subplots()

    df = make_plot_dataframe(
        labels,
        scores,
        class_names,
    )

    # Keep the original interval.
    ax.yaxis.set_major_locator(ticker.MultipleLocator(1))

    # Keep the original seaborn plot settings.
    sns.boxplot(
        x="variable",
        y="value",
        data=df,
        showfliers=False,
        ax=ax,
    )
    sns.stripplot(
        x="variable",
        y="value",
        data=df,
        jitter=True,
        color="black",
        ax=ax,
        size=1.25,
    )

    # Keep the original labels and y-axis range.
    ax.set_xlabel("Mayo score")
    ax.set_ylabel("Score")
    ax.set_ylim([-5, 10])

    ax.tick_params(
        labelbottom=True,
        labelleft=True,
        labelright=False,
        labeltop=False,
    )

    fig.tight_layout()

    # Save as PDF only.
    output_path = os.path.join(
        result_path,
        f"{datatype}_box_plot.pdf",
    )
    fig.savefig(output_path, dpi=300)
    plt.close(fig)


if __name__ == "__main__":
    result_date = str(sys.argv[-1])

    sns.set()
    sns.set_style("whitegrid")
    rc = {"lines.linewidth": 1}
    sns.set_context(
        "poster",
        font_scale=2,
        rc=rc,
    )

    # Keep the original figure size and font-size settings.
    pltsettings(
        fontsize=10,
        figsize=(16, 12),
    )

    class_names = ["M0", "M1", "M2", "M3"]
    fold_list = [1, 2, 3, 4, 5]
    datatype_list = ["train", "valid", "test"]

    for fold in fold_list:
        for datatype in datatype_list:
            result_path = os.path.join(
                "./../Results",
                result_date,
                f"fold_{fold}",
            )

            box_plot(
                result_path=result_path,
                datatype=datatype,
                class_names=class_names,
            )
